INSERT OR IGNORE INTO graph_types ("id","category","name","title","body","properties","archived","revision","createdBy","updatedBy","createdAt","updatedAt") VALUES ('71000000-0000-4000-8000-000000000066','node','KnowledgeGraph','Knowledge graphs','A reusable lens for exploring recorded relationships from a particular node. Document why the graph exists in its body. root_type names its starting node type. pattern lists relationship types, optional traversal directions, and max_depth. Names resolve against this Wiki type registry; UUIDs are also accepted. The lens grants no access or execution rights.','[{"name":"root_type","type":"string","description":"Starting node type registry name or UUID.","required":true},{"name":"pattern","type":"string","description":"JSON relationships and max_depth. A relationship name defaults to outgoing; an object can select incoming.","required":true}]',0,1,'seed:knowledge-graphs-v1','seed:knowledge-graphs-v1',1792886400000,1792886400000);
