INSERT OR IGNORE INTO graph_types ("id","category","name","title","body","properties","archived","revision","createdBy","updatedBy","createdAt","updatedAt") VALUES ('71000000-0000-4000-8000-000000000067','edge','lens_for','lens for','Attach a KnowledgeGraph node to a particular entity it explores. This describes a view, not a business dependency or access grant.

## For agents

Read from the knowledge graph definition to the anchor entity.','[]',0,1,'seed:knowledge-graphs-v1','seed:knowledge-graphs-v1',1792886400000,1792886400000);
