INSERT OR IGNORE INTO graph_nodes ("id","typeId","title","slug","summary","body","website","properties","archived","revision","createdBy","updatedBy","createdAt","updatedAt") VALUES ('74000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000066','Offering dependencies and customer problems','offering-dependencies-knowledge-graph','Understand what an offering packages, what those products depend on, who provides the technology, and whose problems it addresses.','## Why this knowledge graph exists

Explore an offering through its products, dependencies, providers, source repositories, customer problems and affected segments. Follow only the selected recorded relationship types, up to four hops from the offering. Incoming experiences relationships connect problems back to their customer segments. Missing relationships remain gaps, not inferred facts.',NULL,'{"root_type":"Offering","pattern":"{\"relationships\":[\"packages_product\",\"uses\",\"part_of\",\"designed_by\",\"developed_by\",\"addresses\",{\"type\":\"experiences\",\"direction\":\"incoming\"},\"source_in\"],\"max_depth\":4}"}',0,1,'seed:knowledge-graphs-v1','seed:knowledge-graphs-v1',1792886400000,1792886400000);
